-- Reviewed historical imports and their reversal cannot schedule business work.
DROP TRIGGER ticket_version_update;
CREATE TRIGGER ticket_version_update AFTER UPDATE OF updated_at,revision ON conversations WHEN NOT EXISTS(SELECT 1 FROM move_in_native_fences f WHERE f.project_id=NEW.project_id AND f.conversation_id=NEW.id) BEGIN UPDATE conversations SET ticket_version=OLD.ticket_version+1 WHERE id=NEW.id; END;
DROP TRIGGER ticket_closed_terminal;
CREATE TRIGGER ticket_closed_terminal BEFORE UPDATE OF status_id,status_category,resolved_at ON conversations WHEN NOT EXISTS(SELECT 1 FROM move_in_native_fences f WHERE f.project_id=NEW.project_id AND f.conversation_id=NEW.id) AND (OLD.status_category='closed' AND (NEW.status_id<>OLD.status_id OR NEW.status_category<>OLD.status_category OR NEW.resolved_at IS NOT OLD.resolved_at)) BEGIN SELECT RAISE(ABORT,'Closed tickets are final'); END;
DROP TRIGGER ticket_history_update;
CREATE TRIGGER ticket_history_update AFTER UPDATE OF status_id,subject,priority,channel,brand_id,group_id,requester_id,submitter_id,submitter_type ON conversations WHEN NOT EXISTS(SELECT 1 FROM move_in_native_fences f WHERE f.project_id=NEW.project_id AND f.conversation_id=NEW.id) AND (NOT EXISTS(SELECT 1 FROM ticket_history WHERE conversation_id=NEW.id AND at=NEW.updated_at AND actor_id IS NEW.ticket_actor_id AND source=NEW.ticket_source) AND (NEW.status_id<>OLD.status_id OR NEW.subject<>OLD.subject OR NEW.priority<>OLD.priority OR NEW.channel<>OLD.channel OR NEW.brand_id IS NOT OLD.brand_id OR NEW.group_id IS NOT OLD.group_id OR NEW.requester_id IS NOT OLD.requester_id OR NEW.submitter_id IS NOT OLD.submitter_id OR NEW.submitter_type<>OLD.submitter_type)) BEGIN
 INSERT INTO ticket_history VALUES(lower(hex(randomblob(16))),NEW.project_id,NEW.id,NEW.ticket_actor_id,NEW.ticket_actor_type,NEW.ticket_source,NEW.updated_at,json_object('status_id',json_object('from',OLD.status_id,'to',NEW.status_id),'status_category',json_object('from',OLD.status_category,'to',NEW.status_category),'subject',json_object('from',OLD.subject,'to',NEW.subject),'priority',json_object('from',OLD.priority,'to',NEW.priority),'channel',json_object('from',OLD.channel,'to',NEW.channel),'brand_id',json_object('from',OLD.brand_id,'to',NEW.brand_id),'group_id',json_object('from',OLD.group_id,'to',NEW.group_id),'requester_id',json_object('from',OLD.requester_id,'to',NEW.requester_id),'submitter_id',json_object('from',OLD.submitter_id,'to',NEW.submitter_id),'submitter_type',json_object('from',OLD.submitter_type,'to',NEW.submitter_type)));
END;
